export const validateCuratedVenueSeeds = (
  venues: ReadonlyArray<CuratedVenueSeed> = BUCHAREST_VENUES,
) => {
  const names = new Set<string>();
  for (const v of venues) {
    if (!v.hostSlug?.trim()) throw new Error(`${v.name}: hostSlug required`);
    if (!v.name.trim() || !v.address.trim()) throw new Error(`${v.name}: name+address required`);
    if (!v.spaces.length) throw new Error(`${v.name}: at least one space required`);
    const venueHasImg = v.imageSourceUrls.length > 0;
    for (const s of v.spaces) {
      if (!s.shortDescription.trim() || !s.description.trim()) throw new Error(`${v.name}/${s.name}: copy required`);
      if (!venueHasImg && s.imageSourceUrls.length === 0) throw new Error(`${v.name}/${s.name}: no images`);
      for (const a of s.amenityNames) if (!ALLOWED_AMENITIES.has(a)) throw new Error(`${v.name}/${s.name}: bad amenity ${a}`);
    }
    if (names.has(v.name)) throw new Error(`Duplicate venue: ${v.name}`);
    names.add(v.name);
  }
};
